package com.hs.jxc.inv.service;
import com.hs.jxc.common.api.*;
import com.hs.jxc.common.audit.AuditWriter;
import com.hs.jxc.common.context.RequestContext;
import com.hs.jxc.common.db.DbRows;
import com.hs.jxc.common.idempotency.IdempotencyExecutor;
import com.hs.jxc.sys.api.Access;
import com.hs.jxc.sys.service.AuthorizationService;
import java.math.BigDecimal;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
@Service
public class ReplenishmentService {
 private final com.hs.jxc.sys.service.CountryCalendar calendar;private final com.hs.jxc.sys.service.DocumentNumberService numbers;private final JdbcTemplate jdbc;private final AuthorizationService auth;private final IdempotencyExecutor idem;private final AuditWriter audit;private final TransactionTemplate tx;
 public ReplenishmentService(com.hs.jxc.sys.service.CountryCalendar calendar,com.hs.jxc.sys.service.DocumentNumberService numbers,JdbcTemplate jdbc,AuthorizationService auth,IdempotencyExecutor idem,AuditWriter audit,PlatformTransactionManager tm){this.calendar=calendar;this.numbers=numbers;this.jdbc=jdbc;this.auth=auth;this.idem=idem;this.audit=audit;tx=new TransactionTemplate(tm);}
 private void wh(Access a,long wh){if(!a.scope().all()&&!a.scope().warehouses().contains(wh))throw ApiException.notFound();if(jdbc.queryForObject("SELECT count(*) FROM org_warehouse WHERE country_id=? AND id=? AND status='ENABLED'",Integer.class,a.requireCountry(),wh)!=1)throw ApiException.notFound();}
 private Map<String,Object> row(Access a,long id,boolean lock){var rows=jdbc.queryForList("SELECT * FROM inv_replenish WHERE country_id=? AND id=?"+(lock?" FOR UPDATE":""),a.requireCountry(),id);if(rows.isEmpty())throw ApiException.notFound();var r=DbRows.camel(rows.getFirst());wh(a,Inputs.id(r.get("warehouseId")));return r;}
 public Object list(RequestContext c){return tx.execute(s->{var a=auth.authorize(c);a.require("inv:replenish:create","inv:replenish:decide","inv:stock:view");var out=new ArrayList<Map<String,Object>>();for(var raw:jdbc.queryForList("SELECT r.*,w.name warehouse_name,p.product_code,p.name product_name FROM inv_replenish r JOIN org_warehouse w ON w.country_id=r.country_id AND w.id=r.warehouse_id JOIN md_product p ON p.id=r.product_id WHERE r.country_id=? ORDER BY r.id DESC",a.requireCountry())){var r=DbRows.camel(raw);if(!a.scope().all()&&!a.scope().warehouses().contains(Inputs.id(r.get("warehouseId"))))continue;BigDecimal fulfilled=BigDecimal.ZERO;for(var link:jdbc.queryForList("SELECT * FROM inv_replenish_link WHERE country_id=? AND replenish_id=?",a.requireCountry(),r.get("id"))){BigDecimal received;if(link.get("exec_doc_type").equals("INV_TRANSFER"))received=jdbc.queryForObject("SELECT received_qty FROM inv_transfer_line WHERE country_id=? AND id=?",BigDecimal.class,a.requireCountry(),link.get("exec_line_id"));else received=jdbc.queryForObject("SELECT coalesce(sum(rl.good_qty+rl.damaged_qty+rl.pending_inspect_qty),0) FROM lgs_receipt_line rl JOIN lgs_receipt rc ON rc.country_id=rl.country_id AND rc.id=rl.receipt_id JOIN lgs_shipment_line sl ON sl.country_id=rl.country_id AND sl.id=rl.shipment_line_id JOIN lgs_shipment sh ON sh.country_id=sl.country_id AND sh.id=sl.shipment_id WHERE rl.country_id=? AND sl.po_line_id=? AND sh.dest_warehouse_id=? AND rc.status='CONFIRMED'",BigDecimal.class,a.requireCountry(),link.get("exec_line_id"),r.get("warehouseId"));fulfilled=fulfilled.add(received.min((BigDecimal)link.get("qty")));}r.put("fulfilledQty",fulfilled);if(!r.get("status").equals("CLOSED")&&fulfilled.signum()>0)r.put("status",fulfilled.compareTo((BigDecimal)r.get("reqQty"))>=0?"FULFILLED":"PARTIAL");out.add(r);}return Map.of("records",out,"total",out.size());});}
 private long create(Access a,Map<String,Object>b,Long alert){long warehouse=Inputs.id(b.get("warehouseId")),product=Inputs.id(b.get("productId"));wh(a,warehouse);if(jdbc.queryForObject("SELECT count(*) FROM md_country_sku WHERE country_id=? AND product_id=? AND status='ENABLED'",Integer.class,a.requireCountry(),product)!=1)throw Inputs.bad("商品未启用");var qty=Inputs.decimal(b.get("reqQty"),4,new BigDecimal("999999999999"));if(qty.signum()<=0)throw Inputs.bad("需求数量须大于零");long id=jdbc.queryForObject("SELECT nextval('jxc_id_seq')",Long.class);jdbc.update("INSERT INTO inv_replenish(id,country_id,warehouse_id,product_id,alert_id,doc_no,req_qty,need_date,reason,suggested_source) VALUES(?,?,?,?,?,?,?,?,?,?)",id,a.requireCountry(),warehouse,product,alert,numbers.next(a,"REPLENISH",calendar.today(a)),qty,b.get("needDate")==null?null:java.time.LocalDate.parse(b.get("needDate").toString()),Inputs.text(b,"reason",""),Inputs.text(b,"suggestedSource","TRANSFER"));return id;}
 public Object create(RequestContext c,Map<String,Object>b,String key){return tx.execute(s->{var a=auth.authorize(c);a.require("inv:replenish:create");return idem.execute(c,"POST","/api/v1/inv/replenishments",key,b,null,()->{long id=create(a,b,null);audit.append(c,"CREATE","INV_REPLENISH",id,null,b);return row(a,id,false);},r->row(a,Inputs.id(r.get("id")),false));});}
 public Object suggest(RequestContext c,String key){return tx.execute(s->{var a=auth.authorize(c);a.require("inv:replenish:create");return idem.execute(c,"POST","/api/v1/inv/replenishments/suggest",key,Map.of(),null,()->{int count=0;for(var r:jdbc.queryForList("SELECT al.*,lim.max_qty,lim.min_qty FROM inv_stock_alert al JOIN inv_stock_limit lim ON lim.country_id=al.country_id AND lim.warehouse_id=al.warehouse_id AND lim.product_id=al.product_id WHERE al.country_id=? AND al.status='OPEN' AND al.alert_type IN ('BELOW_MIN','OUT_OF_STOCK') ORDER BY al.warehouse_id,al.product_id,al.id FOR UPDATE OF al",a.requireCountry())){long wh=((Number)r.get("warehouse_id")).longValue();if(!a.scope().all()&&!a.scope().warehouses().contains(wh))continue;long alert=((Number)r.get("id")).longValue();if(jdbc.queryForObject("SELECT count(*) FROM inv_replenish WHERE country_id=? AND warehouse_id=? AND product_id=? AND alert_id=? AND status<>'CLOSED'",Integer.class,a.requireCountry(),wh,r.get("product_id"),alert)>0)continue;var threshold=(BigDecimal)(r.get("max_qty")==null?r.get("min_qty"):r.get("max_qty"));if(threshold==null)continue;var qty=threshold.subtract((BigDecimal)r.get("available_qty"));if(qty.signum()<=0)continue;create(a,Map.of("warehouseId",wh,"productId",r.get("product_id"),"reqQty",qty,"reason","库存预警 "+r.get("alert_type")),alert);count++;}return Map.<String,Object>of("created",count);},r->{});});}
 public Object action(RequestContext c,long id,String action,Map<String,Object>b,String key){return tx.execute(s->{var a=auth.authorize(c);a.require("inv:replenish:decide");var r=row(a,id,true);return idem.execute(c,"POST","/api/v1/inv/replenishments/"+id+"/"+action,key,b,null,()->{if(r.get("status").equals("CLOSED"))throw Inputs.conflict();if(action.equals("close"))jdbc.update("UPDATE inv_replenish SET status='CLOSED',decision_note=? WHERE country_id=? AND id=?",Inputs.text(b,"note",""),a.requireCountry(),id);else if(action.equals("decide")){if(!r.get("status").equals("PENDING"))throw Inputs.conflict();String source=Inputs.required(b,"decidedSource");if(!Set.of("TRANSFER","PURCHASE").contains(source))throw Inputs.bad("执行方式不合法");jdbc.update("UPDATE inv_replenish SET status='APPROVED',decided_source=?,decided_by=?,decision_note=? WHERE country_id=? AND id=?",source,a.userId(),Inputs.text(b,"note",""),a.requireCountry(),id);}else if(action.equals("link")){if(!Set.of("APPROVED","LINKED").contains(r.get("status")))throw Inputs.conflict();String type=Inputs.required(b,"execDocType");long target=Inputs.id(b.get("execDocId"));boolean transfer=type.equals("INV_TRANSFER");if(!transfer&&!type.equals("PUR_ORDER")||!Objects.equals(r.get("decidedSource"),transfer?"TRANSFER":"PURCHASE"))throw Inputs.bad("执行单与批准的执行方式不符");List<Map<String,Object>> lines;if(transfer){var doc=jdbc.queryForList("SELECT * FROM inv_transfer WHERE country_id=? AND id=? AND to_warehouse_id=? AND status IN ('APPROVED','IN_TRANSIT','PARTIAL_RECEIVED','RECEIVED','CLOSED') FOR UPDATE",a.requireCountry(),target,r.get("warehouseId"));if(doc.isEmpty())throw ApiException.notFound();lines=jdbc.queryForList("SELECT id,qty FROM inv_transfer_line WHERE country_id=? AND transfer_id=? AND product_id=? ORDER BY id FOR UPDATE",a.requireCountry(),target,r.get("productId"));}else{a.require("pur:order:view");var doc=jdbc.queryForList("SELECT * FROM pur_order WHERE country_id=? AND id=? AND status IN ('CONFIRMED','PARTIAL_DELIVERED','DELIVERED','CLOSED') FOR UPDATE",a.requireCountry(),target);if(doc.isEmpty())throw ApiException.notFound();a.requireRow(DbRows.camel(doc.getFirst()));lines=jdbc.queryForList("SELECT id,base_qty-cancelled_qty qty FROM pur_order_line WHERE country_id=? AND order_id=? AND product_id=? ORDER BY id FOR UPDATE",a.requireCountry(),target,r.get("productId"));}if(lines.isEmpty())throw Inputs.bad("执行单没有该商品");var already=jdbc.queryForObject("SELECT coalesce(sum(qty),0) FROM inv_replenish_link WHERE country_id=? AND replenish_id=?",BigDecimal.class,a.requireCountry(),id);BigDecimal left=((BigDecimal)r.get("reqQty")).subtract(already);for(var line:lines){if(left.signum()<=0)break;var assigned=jdbc.queryForObject("SELECT coalesce(sum(qty),0) FROM inv_replenish_link WHERE country_id=? AND exec_doc_type=? AND exec_line_id=?",BigDecimal.class,a.requireCountry(),type,line.get("id"));var take=left.min(((BigDecimal)line.get("qty")).subtract(assigned));if(take.signum()<=0)continue;jdbc.update("INSERT INTO inv_replenish_link(country_id,replenish_id,exec_doc_type,exec_doc_id,exec_line_id,qty,transfer_id,transfer_line_id,purchase_order_id,purchase_order_line_id) VALUES(?,?,?,?,?,?,?,?,?,?)",a.requireCountry(),id,type,target,line.get("id"),take,transfer?target:null,transfer?line.get("id"):null,transfer?null:target,transfer?null:line.get("id"));left=left.subtract(take);}if(left.compareTo(((BigDecimal)r.get("reqQty")).subtract(already))==0)throw Inputs.bad("执行数量已被关联，不能重复占用");jdbc.update("UPDATE inv_replenish SET status='LINKED' WHERE country_id=? AND id=?",a.requireCountry(),id);}else throw Inputs.bad("补货操作不合法");audit.append(c,action.toUpperCase(Locale.ROOT),"INV_REPLENISH",id,r,b);return row(a,id,false);},out->row(a,id,false));});}
}
